CREATE DATABASE IF NOT EXISTS inmobiliaria_uts CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE inmobiliaria_uts;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS auditoria, favorito, documento_solicitud, solicitud, cita, propiedad_caracteristica, imagen_propiedad, propiedad, inmobiliaria, perfil, usuario_rol, usuario, caracteristica, tipo_propiedad, ciudad, rol;
SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE rol (id_rol INT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(30) NOT NULL UNIQUE, descripcion VARCHAR(150) NOT NULL);
CREATE TABLE usuario (id_usuario INT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(80) NOT NULL, correo VARCHAR(120) NOT NULL UNIQUE, telefono VARCHAR(30), clave VARCHAR(64) NOT NULL, activo TINYINT(1) NOT NULL DEFAULT 1, creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE usuario_rol (id_usuario INT NOT NULL, id_rol INT NOT NULL, PRIMARY KEY (id_usuario,id_rol), FOREIGN KEY (id_usuario) REFERENCES usuario(id_usuario) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (id_rol) REFERENCES rol(id_rol) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE perfil (id_perfil INT AUTO_INCREMENT PRIMARY KEY, id_usuario INT NOT NULL UNIQUE, documento VARCHAR(30), direccion VARCHAR(180), ciudad VARCHAR(80), FOREIGN KEY (id_usuario) REFERENCES usuario(id_usuario) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE inmobiliaria (id_inmobiliaria INT AUTO_INCREMENT PRIMARY KEY, id_usuario INT NOT NULL, nombre VARCHAR(120) NOT NULL, nit VARCHAR(30) NOT NULL UNIQUE, telefono VARCHAR(30), activa TINYINT(1) DEFAULT 1, FOREIGN KEY (id_usuario) REFERENCES usuario(id_usuario) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE ciudad (id_ciudad INT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(80) NOT NULL UNIQUE, departamento VARCHAR(80) NOT NULL, activa TINYINT(1) DEFAULT 1);
CREATE TABLE tipo_propiedad (id_tipo INT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(50) NOT NULL UNIQUE, descripcion VARCHAR(150), activo TINYINT(1) DEFAULT 1);
CREATE TABLE propiedad (id_propiedad INT AUTO_INCREMENT PRIMARY KEY, id_inmobiliaria INT NOT NULL, id_ciudad INT NOT NULL, id_tipo INT NOT NULL, matricula_inmobiliaria VARCHAR(40) NOT NULL UNIQUE, titulo VARCHAR(150) NOT NULL, descripcion TEXT, direccion VARCHAR(180) NOT NULL, precio DECIMAL(14,2) NOT NULL, area DECIMAL(10,2) NOT NULL, habitaciones INT NOT NULL DEFAULT 0, banos INT NOT NULL DEFAULT 0, estado VARCHAR(20) NOT NULL DEFAULT 'DISPONIBLE', activo TINYINT(1) NOT NULL DEFAULT 1, creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (id_inmobiliaria) REFERENCES inmobiliaria(id_inmobiliaria) ON DELETE RESTRICT ON UPDATE CASCADE, FOREIGN KEY (id_ciudad) REFERENCES ciudad(id_ciudad) ON DELETE RESTRICT ON UPDATE CASCADE, FOREIGN KEY (id_tipo) REFERENCES tipo_propiedad(id_tipo) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE imagen_propiedad (id_imagen INT AUTO_INCREMENT PRIMARY KEY, id_propiedad INT NOT NULL, url VARCHAR(400) NOT NULL, texto_alternativo VARCHAR(150), orden INT DEFAULT 1, FOREIGN KEY (id_propiedad) REFERENCES propiedad(id_propiedad) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE caracteristica (id_caracteristica INT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(80) NOT NULL UNIQUE, activo TINYINT(1) DEFAULT 1);
CREATE TABLE propiedad_caracteristica (id_propiedad INT NOT NULL, id_caracteristica INT NOT NULL, PRIMARY KEY (id_propiedad,id_caracteristica), FOREIGN KEY (id_propiedad) REFERENCES propiedad(id_propiedad) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (id_caracteristica) REFERENCES caracteristica(id_caracteristica) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE cita (id_cita INT AUTO_INCREMENT PRIMARY KEY, id_propiedad INT NOT NULL, id_usuario INT NOT NULL, fecha_hora DATETIME NOT NULL, estado VARCHAR(20) NOT NULL DEFAULT 'PENDIENTE', observaciones VARCHAR(300), UNIQUE KEY uq_cita_horario (id_propiedad,fecha_hora), FOREIGN KEY (id_propiedad) REFERENCES propiedad(id_propiedad) ON DELETE RESTRICT ON UPDATE CASCADE, FOREIGN KEY (id_usuario) REFERENCES usuario(id_usuario) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE solicitud (id_solicitud INT AUTO_INCREMENT PRIMARY KEY, id_propiedad INT NOT NULL, id_usuario INT NOT NULL, tipo VARCHAR(20) NOT NULL, estado VARCHAR(20) NOT NULL DEFAULT 'EN_REVISION', creada_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (id_propiedad) REFERENCES propiedad(id_propiedad) ON DELETE RESTRICT ON UPDATE CASCADE, FOREIGN KEY (id_usuario) REFERENCES usuario(id_usuario) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE documento_solicitud (id_documento INT AUTO_INCREMENT PRIMARY KEY, id_solicitud INT NOT NULL, nombre_archivo VARCHAR(180) NOT NULL, url VARCHAR(400), estado VARCHAR(20) DEFAULT 'PENDIENTE', FOREIGN KEY (id_solicitud) REFERENCES solicitud(id_solicitud) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE favorito (id_usuario INT NOT NULL, id_propiedad INT NOT NULL, creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (id_usuario,id_propiedad), FOREIGN KEY (id_usuario) REFERENCES usuario(id_usuario) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (id_propiedad) REFERENCES propiedad(id_propiedad) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE auditoria (id_auditoria INT AUTO_INCREMENT PRIMARY KEY, id_usuario INT, accion VARCHAR(120) NOT NULL, tabla_afectada VARCHAR(80), id_registro INT, detalle VARCHAR(300), creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (id_usuario) REFERENCES usuario(id_usuario) ON DELETE RESTRICT ON UPDATE CASCADE);

